#!/usr/bin/env python3
"""Regenerates the "bits" region of crypto/proof_bits.bend.

  python3 gen/proof.py           rewrite the region between the lines
                                 "# BEGIN GENERATED by gen/proof.py: bits"
                                 and "# END GENERATED: bits"
  python3 gen/proof.py --check   only check that it is up to date

The region holds the lemmas proved on a word's 32 bits: each splits its
32-bit arguments into their bits with a deep pattern (U32{WCon{b0, ...
WNil{}}}) and then holds by computation ({==}). Everything outside the region
is written by hand.
"""
import os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
PROOF = os.path.join(HERE, "..", "proof_bits.bend")


def u32(p):
    """the pattern splitting a U32 into its bits p0 .. p31"""
    return "U32{" + "".join("WCon{%s%d, " % (p, i) for i in range(32)) + "WNil{}" + "}" * 32 + "}"


def lemma(comment, sig, names, prefixes):
    """a lemma whose U32 arguments (names) are split into bits named by prefixes"""
    pats = " ".join(u32(p) for p in prefixes)
    return "# %s\ndef %s:\n  match %s:\n    case %s:\n      {==}\n" % (comment, sig, " ".join(names), pats)


def bits_region():
    out = []
    out.append(lemma("the low byte of a XOR depends only on the low byte of its first operand",
                     "byte_xor_byte(z: U32, k: U32) -> {B.byte(U32.xor(z, k)) == B.byte(U32.xor(B.byte(z), k)) : U32}",
                     ["z", "k"], ["a", "b"]))
    out.append(lemma("0 XOR a word is the word",
                     "u32_xor0(y: U32) -> {U32.xor(0, y) == y : U32}",
                     ["y"], ["a"]))
    out.append(lemma("a word's big-endian bytes are four",
                     "be32_len(v: U32) -> {B.Octets.len(B.Octets.be32(v)) == 4n : Nat}",
                     ["v"], ["a"]))
    out.append("# a 128-bit block's 16 bytes, masked and read back\n"
               "def f128_bytes(b: M.CmBlock) -> {CM.cr.f128.block(B.mask(CM.cr.f128.bytes(b))) == Some{b} : Maybe<&2, M.CmBlock>}:\n"
               "  match b:\n    case M.CmBlock{%s}:\n      {==}\n" % ", ".join(u32(p) for p in "acde"))
    return "\n".join(out)


def main():
    check = "--check" in sys.argv[1:]
    with open(PROOF) as f:
        text = f.read()
    name = "bits"
    begin = "# BEGIN GENERATED by gen/proof.py: %s\n" % name
    end = "# END GENERATED: %s\n" % name
    i, j = text.index(begin) + len(begin), text.index(end)
    new = text[:i] + bits_region() + text[j:]
    if check:
        if new != text:
            print("proof_bits.bend: region %s is out of date (run gen/proof.py)" % name)
            sys.exit(1)
        print("proof_bits.bend: up to date")
        return
    with open(PROOF, "w", newline="\n") as f:
        f.write(new)


if __name__ == "__main__":
    main()
